import type { VoiceLanguage } from '../types'
import titleVoices from '../data/titleVoices.json'

export interface TitleVoice {
  charId: string
  operator: string
  src: string
}

// Generated by scripts/voice-pipeline/gen_title_voices.py — one pool per voice language that has
// been extracted so far. Run the script with `--lang jp|cn|kr` to add the others.
const TITLE_VOICES_BY_LANGUAGE = titleVoices as Partial<Record<VoiceLanguage, TitleVoice[]>>

export const DEFAULT_VOICE_LANGUAGE: VoiceLanguage = 'EN'

/** A random operator's "Title" line ("Arknights!") in `language`, falling back to EN when that pool is empty. */
export function pickTitleVoice(language: VoiceLanguage = DEFAULT_VOICE_LANGUAGE): TitleVoice | null {
  const pool = TITLE_VOICES_BY_LANGUAGE[language]?.length
    ? TITLE_VOICES_BY_LANGUAGE[language]!
    : TITLE_VOICES_BY_LANGUAGE[DEFAULT_VOICE_LANGUAGE] ?? []
  if (pool.length === 0) return null
  return pool[Math.floor(Math.random() * pool.length)]
}
